
(async () => {
  const b64 = "";
  const bin = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
  const file = new File([bin], "linkedin-cover-1584x396.png", { type: "image/png" });
  const input = document.querySelector('input[type=file][accept*="image"]') || document.querySelector('input[type=file]');
  if (!input) return { ok: false, reason: "no-file-input" };
  const dt = new DataTransfer();
  dt.items.add(file);
  input.files = dt.files;
  input.dispatchEvent(new Event("input", { bubbles: true }));
  input.dispatchEvent(new Event("change", { bubbles: true }));
  return { ok: true, count: input.files.length, name: input.files[0] && input.files[0].name, size: input.files[0] && input.files[0].size };
})()
